import { FormEvent, type ReactNode, useCallback, useEffect, useState } from 'react'
import { Link, useLocation, useNavigate, useParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { ArrowLeftRight, Boxes, ClipboardList, Factory, PackageCheck, PackageMinus, PackagePlus, Warehouse as WarehouseIcon } from 'lucide-react'
import { useAuth } from './AuthContext'
import { formatBusinessDate } from './i18n/businessDate'
import { localizedName } from './i18n/localizedName'
import { formatOperationalNumber } from './i18n/numberFormatting'
import { normalizeJalaliDateInput, toAsciiDigits } from './mrpRunUiSupport'
import { buildTransactionListQuery } from './inventoryUiSupport'
import { ConfirmationDialog, DataTable, FilterBar, FormField, MessageStrip, PageHeader, Pagination, Section, StatusBadge, TableToolbar } from './ui'
import { currentListContext, useListQuery, useListReturn } from './ui/routeContext'

type Unit = { id: string; code: string; nameFa: string; nameEn?: string | null; symbol?: string | null; isActive: boolean }
type Item = { id: string; code: string; itemType: string; nameFa: string; nameEn?: string | null; isActive: boolean; baseUnit: Unit }
type ResponsibleUser = { id: string; userName: string; fullName: string; photoUrl: string; isActive: boolean }
type Warehouse = { id: string; code: string; nameFa: string; nameEn?: string | null; addressFa?: string | null; addressEn?: string | null; primaryResponsibleUser?: ResponsibleUser | null; warehouseType: string; includeInMrpAvailable: boolean; isActive: boolean; notes?: string | null; version: number }
type Balance = { item: Item; warehouse: Warehouse; actualOnHand: number; inactiveWarehouseStockWarning: boolean }
type Position = { asOfDate: string; item: Item; usablePhysicalTotal: number; productionStagingTotal: number; inTransitTotal: number; companyOwnedTotal: number; hasInactiveWarehouseStockWarning: boolean; warehouses: { warehouse: Warehouse; actualOnHand: number; inactiveWarehouseStockWarning: boolean }[] }
type Overview = { asOfDate: string; activeWarehouseCount: number; inactiveWarehouseCount: number; itemPositionCount: number; totalInTransit: number; openTransferCount: number; negativeBalanceCount: number }
type Transaction = { id: string; transactionType: string; item: Item; warehouse: Warehouse; destinationWarehouse?: Warehouse | null; quantity: number; unit: Unit; enteredQuantity: number; transactionUnit: Unit; conversionFactorToBase: number; effectiveDate: string; reason?: string | null; originalTransactionId?: string | null; sourceDocumentType?: string | null; sourceDocumentId?: string | null; createdAtUtc: string }
type TransferReceipt = { id: string; quantity: number; enteredQuantity: number; transactionUnit: Unit; conversionFactorToBase: number; effectiveDate: string; reason?: string | null; inventoryTransactionId: string; isReversed: boolean; createdAtUtc: string }
type Transfer = { id: string; code: string; status: string; item: Item; unit: Unit; sourceWarehouse: Warehouse; destinationWarehouse: Warehouse; requestedQuantity: number; enteredRequestedQuantity: number; transactionUnit: Unit; conversionFactorToBase: number; dispatchedQuantity: number; receivedQuantity: number; inTransitQuantity: number; dispatchDate?: string | null; reason?: string | null; cancellationReason?: string | null; version: number; createdAtUtc: string; updatedAtUtc: string; receipts: TransferReceipt[] }
type UnitConversion = { id?: string | null; transactionUnit: Unit; baseUnit: Unit; factorToBase: number; isBaseUnit: boolean; isActive: boolean; version: number }
type UnitConversionList = { item: Item; items: UnitConversion[] }
type Page<T> = { items: T[]; page: number; pageSize: number; totalCount: number }
type View = 'overview' | 'balances' | 'item' | 'warehouses' | 'warehouse' | 'transactions' | 'transaction' | 'operation' | 'transfers' | 'transfer' | 'transferCreate'
type Operation = 'OPENING' | 'RECEIPT' | 'ISSUE' | 'ADJUSTMENT'
const api = (import.meta.env.VITE_API_BASE_URL ?? '/api').replace(/\/$/, '')

export default function InventoryPage({ view, operation }: { view: View; operation?: Operation }) {
  if (view === 'overview') return <InventoryOverview />
  if (view === 'balances') return <BalanceList />
  if (view === 'item') return <ItemPosition />
  if (view === 'warehouses') return <WarehouseList />
  if (view === 'warehouse') return <WarehouseObject />
  if (view === 'transactions') return <TransactionList />
  if (view === 'transaction') return <TransactionObject />
  if (view === 'transfers') return <TransferList />
  if (view === 'transfer') return <TransferObject />
  if (view === 'transferCreate') return <TransferCreate />
  return <PostingPage operation={operation ?? 'RECEIPT'} />
}

function InventoryOverview() {
  const { t, i18n } = useTranslation(); const [data, setData] = useState<Overview>(); const [error, setError] = useState('')
  useEffect(() => { void get<Overview>('/inventory/overview').then(setData).catch(e => setError(message(e, t))) }, [t])
  return <main className="app-shell inventory-workspace"><PageHeader title={t('inventory.workspaceTitle')} subtitle={t('inventory.workspaceDescription')} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}{data && <><section className="inventory-kpi-grid"><Kpi icon={<WarehouseIcon />} label={t('inventory.activeWarehouses')} value={data.activeWarehouseCount} /><Kpi icon={<Boxes />} label={t('inventory.itemPositions')} value={data.itemPositionCount} /><Kpi icon={<ArrowLeftRight />} label={t('inventory.inTransit')} value={data.totalInTransit} /><Kpi icon={<ClipboardList />} label={t('inventory.openTransfers')} value={data.openTransferCount} /></section>{data.negativeBalanceCount > 0 && <MessageStrip tone="critical">{t('inventory.negativeBalanceDetected', { count: data.negativeBalanceCount })}</MessageStrip>}<Section title={t('inventory.quickActions')} description={`${t('inventory.asOf')} ${formatBusinessDate(data.asOfDate, i18n.resolvedLanguage ?? 'fa-IR')}`}><div className="inventory-action-grid"><ActionCard to="/inventory/items" icon={<Boxes />} title={t('inventory.itemPositions')} hint={t('inventory.itemsHint')} /><ActionCard to="/inventory/operations/receipt" icon={<PackagePlus />} title={t('inventory.receipt')} hint={t('inventory.receiptHint')} /><ActionCard to="/inventory/operations/issue" icon={<PackageMinus />} title={t('inventory.issue')} hint={t('inventory.issueHint')} /><ActionCard to="/inventory/transfers" icon={<ArrowLeftRight />} title={t('inventory.transfers')} hint={t('inventory.transferHint')} /><ActionCard to="/inventory/warehouses" icon={<WarehouseIcon />} title={t('inventory.warehouses')} hint={t('inventory.warehouseHint')} /></div></Section></>}</main>
}

function Kpi({ icon, label, value }: { icon: ReactNode; label: string; value: number }) { const { i18n } = useTranslation(); return <article className="inventory-kpi"><span>{icon}</span><div><small>{label}</small><strong className="ui-number">{formatOperationalNumber(value, i18n.resolvedLanguage)}</strong></div></article> }
function ActionCard({ to, icon, title, hint }: { to: string; icon: ReactNode; title: string; hint: string }) { return <Link className="inventory-action-card" to={to}><span>{icon}</span><div><strong>{title}</strong><small>{hint}</small></div></Link> }

function BalanceList() {
  const { t, i18n } = useTranslation(); const query = useListQuery(25); const location = useLocation(); const [rows, setRows] = useState<Balance[]>([]); const [total, setTotal] = useState(0); const [loading, setLoading] = useState(true); const [error, setError] = useState('')
  const search = query.value('search'); const itemType = query.value('itemType'); const asOfDate = query.value('asOfDate'); const display = (x: { nameFa: string; nameEn?: string | null }) => localizedName(x, i18n.resolvedLanguage)
  useEffect(() => { let active = true; const language = i18n.resolvedLanguage ?? 'fa-IR'; if (!dateFilterReady(asOfDate, language)) return () => { active = false }; void (async () => { try { const params = new URLSearchParams({ search, itemType, page: String(query.page), pageSize: String(query.pageSize) }); if (asOfDate) params.set('asOfDate', await canonicalDate(asOfDate, language)); const x = await get<Page<Balance>>(`/inventory/balances?${params}`); if (active) { setRows(x.items); setTotal(x.totalCount) } } catch (e) { if (active) setError(message(e, t)) } finally { if (active) setLoading(false) } })(); return () => { active = false } }, [asOfDate, i18n.resolvedLanguage, itemType, query.page, query.pageSize, search, t])
  return <main className="app-shell"><PageHeader title={t('inventory.itemPositions')} subtitle={t('inventory.physicalTruthHint')} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}<FilterBar label={t('common.filterBar')}><FormField label={t('common.search')}><input value={search} onChange={e => query.update({ search: e.target.value }, true)} placeholder={t('inventory.searchItem')} /></FormField><FormField label={t('inventory.itemType')}><select value={itemType} onChange={e => query.update({ itemType: e.target.value }, true)}><option value="">{t('common.all')}</option><option>PRODUCT</option><option>PART</option><option>COMPONENT</option></select></FormField><DateFilterField label={t('inventory.asOf')} value={asOfDate} setValue={value => query.update({ asOfDate: value }, true)} /></FilterBar><section className="ui-table-surface"><TableToolbar title={t('inventory.itemPositions')} count={t('common.count', { count: total })} /><DataTable headers={[t('common.code'), t('inventory.item'), t('inventory.warehouse'), t('inventory.physicalOnHand'), t('common.unit')]} loading={loading} empty={!rows.length} filtered={Boolean(search || itemType || asOfDate)} loadingLabel={t('common.loading')} emptyTitle={t('common.emptyTitle')} noResultTitle={t('common.noResultsTitle')}>{rows.map(row => <tr key={`${row.item.id}-${row.warehouse.id}`}><td><Link className="ui-technical" to={`/inventory/items/${row.item.id}?from=${currentListContext(location.pathname, location.search)}`}>{row.item.code}</Link></td><td>{display(row.item)}</td><td>{row.warehouse.code} — {display(row.warehouse)}{row.inactiveWarehouseStockWarning && <StatusBadge text={t('common.inactive')} tone="warning" />}</td><td className="ui-number">{formatOperationalNumber(row.actualOnHand, i18n.resolvedLanguage)}</td><td>{display(row.item.baseUnit)}</td></tr>)}</DataTable><PageNav page={query.page} pageSize={query.pageSize} total={total} change={page => query.update({ page })} /></section></main>
}

function ItemPosition() {
  const { t, i18n } = useTranslation(); const { has } = useAuth(); const { id } = useParams(); const back = useListReturn('/inventory/items'); const [data, setData] = useState<Position>(); const [conversions, setConversions] = useState<UnitConversion[]>([]); const [units, setUnits] = useState<Unit[]>([]); const [unitId, setUnitId] = useState(''); const [factor, setFactor] = useState(''); const [drafts, setDrafts] = useState<Record<string, string>>({}); const [error, setError] = useState(''); const display = (x: { nameFa: string; nameEn?: string | null }) => localizedName(x, i18n.resolvedLanguage)
  const load = useCallback(async () => { try { const [position, unitRows, allUnits] = await Promise.all([get<Position>(`/inventory/items/${id}/position`), get<UnitConversionList>(`/inventory/items/${id}/units?includeInactive=true`), get<Unit[]>('/reference-data/units?includeInactive=true')]); setData(position); setConversions(unitRows.items); setUnits(allUnits); setDrafts(Object.fromEntries(unitRows.items.filter(x => x.id).map(x => [x.id!, String(x.factorToBase)]))) } catch (e) { setError(message(e, t)) } }, [id, t])
  useEffect(() => { void Promise.resolve().then(load) }, [load])
  async function addUnit(event: FormEvent) { event.preventDefault(); try { await request(`/inventory/items/${id}/units`, 'POST', { transactionUnitId: unitId, factorToBase: Number(factor) }); setUnitId(''); setFactor(''); await load() } catch (e) { setError(message(e, t)) } }
  async function updateUnit(row: UnitConversion) { if (!row.id) return; try { await request(`/inventory/items/${id}/units/${row.id}`, 'PUT', { factorToBase: Number(drafts[row.id]), expectedVersion: row.version }); await load() } catch (e) { setError(message(e, t)) } }
  async function stateUnit(row: UnitConversion) { if (!row.id) return; try { await request(`/inventory/items/${id}/units/${row.id}/${row.isActive ? 'deactivate' : 'reactivate'}`, 'POST', { expectedVersion: row.version, reason: null }); await load() } catch (e) { setError(message(e, t)) } }
  return <main className="app-shell"><PageHeader title={data ? `${data.item.code} — ${display(data.item)}` : t('inventory.itemPosition')} subtitle={t('inventory.itemPosition')} backTo={back} backLabel={t('common.backToList')} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}{data && <><section className="inventory-kpi-grid"><Kpi icon={<PackageCheck />} label={t('inventory.usablePhysical')} value={data.usablePhysicalTotal} /><Kpi icon={<Factory />} label={t('inventory.productionStaging')} value={data.productionStagingTotal} /><Kpi icon={<ArrowLeftRight />} label={t('inventory.inTransit')} value={data.inTransitTotal} /><Kpi icon={<Boxes />} label={t('inventory.companyOwned')} value={data.companyOwnedTotal} /></section>{data.hasInactiveWarehouseStockWarning && <MessageStrip tone="warning">{t('inventory.inactiveStock')}</MessageStrip>}<Section title={t('inventory.warehouseBreakdown')}><DataTable headers={[t('common.code'), t('inventory.warehouse'), t('inventory.warehouseType'), t('inventory.physicalOnHand'), t('common.status')]} loadingLabel={t('common.loading')} emptyTitle={t('common.emptyTitle')} noResultTitle={t('common.noResultsTitle')} empty={!data.warehouses.length}>{data.warehouses.map(row => <tr key={row.warehouse.id}><td className="ui-technical">{row.warehouse.code}</td><td>{display(row.warehouse)}</td><td>{t(`inventory.warehouseTypes.${row.warehouse.warehouseType}`)}</td><td className="ui-technical">{row.actualOnHand}</td><td><StatusBadge text={row.warehouse.isActive ? t('common.active') : t('common.inactive')} tone={row.warehouse.isActive ? 'positive' : 'warning'} /></td></tr>)}</DataTable></Section><Section title={t('inventory.transactionUnits')} description={t('inventory.transactionUnitsHint')}><DataTable headers={[t('common.unit'), t('inventory.factorToBase'), t('inventory.baseEquivalent'), t('common.status'), t('common.actions')]} loadingLabel={t('common.loading')} emptyTitle={t('common.emptyTitle')} noResultTitle={t('common.noResultsTitle')} empty={!conversions.length}>{conversions.map(row => <tr key={row.id || 'base'}><td>{row.transactionUnit.code} — {display(row.transactionUnit)}</td><td>{row.isBaseUnit ? <span className="technical-value">1</span> : <input className="inventory-factor-input" disabled={!has('inventory.item_unit.manage')} type="number" min="0.000000000001" step="0.000001" value={drafts[row.id!] ?? row.factorToBase} onChange={e => setDrafts({ ...drafts, [row.id!]: e.target.value })} />}</td><td className="technical-value">1 {row.transactionUnit.code} = {row.factorToBase} {row.baseUnit.code}</td><td><StatusBadge text={row.isActive ? t('common.active') : t('common.inactive')} tone={row.isActive ? 'positive' : 'neutral'} /></td><td>{row.id && has('inventory.item_unit.manage') && <><button className="button button--compact" type="button" onClick={() => void updateUnit(row)}>{t('common.save')}</button><button className="button button--compact button--quiet" type="button" onClick={() => void stateUnit(row)}>{row.isActive ? t('common.deactivate') : t('common.reactivate')}</button></>}</td></tr>)}</DataTable>{has('inventory.item_unit.manage') && <form className="ui-form-grid ui-form-grid--3 inventory-unit-form" onSubmit={e => void addUnit(e)}><FormField label={t('inventory.transactionUnit')} required><select required value={unitId} onChange={e => setUnitId(e.target.value)}><option value="">{t('common.notSet')}</option>{units.filter(unit => unit.id !== data.item.baseUnit.id && !conversions.some(row => row.transactionUnit.id === unit.id)).map(unit => <option key={unit.id} value={unit.id}>{unit.code} — {display(unit)}</option>)}</select></FormField><FormField label={t('inventory.factorToBase')} hint={t('inventory.factorExample')} required><input required type="number" min="0.000000000001" step="0.000001" value={factor} onChange={e => setFactor(e.target.value)} /></FormField><button className="button button--primary">{t('common.create')}</button></form>}</Section></>}</main>
}

function WarehouseList() {
  const { t, i18n } = useTranslation(); const { has } = useAuth(); const query = useListQuery(25); const location = useLocation(); const [rows, setRows] = useState<Warehouse[]>([]); const [total, setTotal] = useState(0); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const search = query.value('search'); const includeInactive = query.flag('includeInactive'); const display = (x: Warehouse) => localizedName(x, i18n.resolvedLanguage)
  const load = useCallback(() => { const q = new URLSearchParams({ search, includeInactive: String(includeInactive), page: String(query.page), pageSize: String(query.pageSize) }); return get<Page<Warehouse>>(`/inventory/warehouses?${q}`).then(x => { setRows(x.items); setTotal(x.totalCount) }).catch(e => setError(message(e, t))).finally(() => setLoading(false)) }, [includeInactive, query.page, query.pageSize, search, t])
  useEffect(() => { void load() }, [load])
  return <main className="app-shell"><PageHeader title={t('inventory.warehouses')} subtitle={t('inventory.warehouseHint')} actions={has('inventory.warehouse.manage') ? <Link className="button button--primary" to={`/inventory/warehouses/new?from=${currentListContext(location.pathname, location.search)}`}>{t('inventory.newWarehouse')}</Link> : undefined} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}<FilterBar label={t('common.filterBar')}><FormField label={t('common.search')}><input value={search} onChange={e => query.update({ search: e.target.value }, true)} /></FormField><label className="checkbox-label"><input type="checkbox" checked={includeInactive} onChange={e => query.update({ includeInactive: e.target.checked }, true)} />{t('common.includeInactive')}</label></FilterBar><section className="ui-table-surface"><TableToolbar title={t('inventory.warehouses')} count={t('common.count', { count: total })} /><DataTable headers={[t('common.code'), t('inventory.warehouse'), t('inventory.warehouseType'), t('inventory.location'), t('inventory.responsible'), t('common.status')]} loading={loading} empty={!rows.length} filtered={Boolean(search || includeInactive)} loadingLabel={t('common.loading')} emptyTitle={t('common.emptyTitle')} noResultTitle={t('common.noResultsTitle')}>{rows.map(x => <tr key={x.id}><td><Link className="ui-technical" to={`/inventory/warehouses/${x.id}?from=${currentListContext(location.pathname, location.search)}`}>{x.code}</Link></td><td>{display(x)}</td><td><StatusBadge text={t(`inventory.warehouseTypes.${x.warehouseType}`)} tone={x.includeInMrpAvailable ? 'positive' : 'warning'} /></td><td>{i18n.resolvedLanguage?.startsWith('en') ? x.addressEn || x.addressFa : x.addressFa}</td><td>{x.primaryResponsibleUser?.fullName || '—'}</td><td><StatusBadge text={x.isActive ? t('common.active') : t('common.inactive')} tone={x.isActive ? 'positive' : 'neutral'} /></td></tr>)}</DataTable><PageNav page={query.page} pageSize={query.pageSize} total={total} change={page => query.update({ page })} /></section></main>
}

function WarehouseObject() {
  const { t, i18n } = useTranslation(); const { has } = useAuth(); const { id } = useParams(); const location = useLocation(); const navigate = useNavigate(); const back = useListReturn('/inventory/warehouses'); const editing = location.pathname.endsWith('/edit') || !id; const [warehouse, setWarehouse] = useState<Warehouse>(); const [users, setUsers] = useState<ResponsibleUser[]>([]); const [userSearch, setUserSearch] = useState(''); const [form, setForm] = useState({ nameFa: '', nameEn: '', addressFa: '', addressEn: '', primaryResponsibleUserId: '', notes: '', warehouseType: 'STORAGE' }); const [error, setError] = useState(''); const [confirm, setConfirm] = useState(false)
  useEffect(() => { if (!id) return; void get<Warehouse>(`/inventory/warehouses/${id}`).then(x => { setWarehouse(x); setUsers(existing => x.primaryResponsibleUser ? uniqueById([...existing, x.primaryResponsibleUser]) : existing); setForm({ nameFa: x.nameFa, nameEn: x.nameEn || '', addressFa: x.addressFa || '', addressEn: x.addressEn || '', primaryResponsibleUserId: x.primaryResponsibleUser?.id || '', notes: x.notes || '', warehouseType: x.warehouseType }) }).catch(e => setError(message(e, t))) }, [id, t])
  useEffect(() => { if (!editing) return; const timer = window.setTimeout(() => { const q = new URLSearchParams({ search: userSearch, page: '1', pageSize: '25' }); void get<Page<ResponsibleUser>>(`/inventory/responsible-users?${q}`).then(x => setUsers(existing => uniqueById([...existing, ...x.items]))).catch(e => setError(message(e, t))) }, 150); return () => window.clearTimeout(timer) }, [editing, t, userSearch])
  async function save(event: FormEvent) { event.preventDefault(); try { const body = id ? { ...form, expectedVersion: warehouse!.version } : form; const result = await request<Warehouse>(id ? `/inventory/warehouses/${id}` : '/inventory/warehouses', id ? 'PUT' : 'POST', body); setWarehouse(result); navigate(`/inventory/warehouses/${result.id}?from=${encodeURIComponent(back)}`) } catch (e) { setError(message(e, t)) } }
  async function state() { if (!warehouse) return; try { const result = await request<Warehouse>(`/inventory/warehouses/${warehouse.id}/${warehouse.isActive ? 'deactivate' : 'reactivate'}`, 'POST', { expectedVersion: warehouse.version, reason: null }); setWarehouse(result); setConfirm(false) } catch (e) { setError(message(e, t)); setConfirm(false) } }
  const displayAddress = i18n.resolvedLanguage?.startsWith('en') ? warehouse?.addressEn || warehouse?.addressFa : warehouse?.addressFa
  return <main className="app-shell"><PageHeader title={id ? `${warehouse?.code ?? ''} — ${t('inventory.warehouse')}` : t('inventory.newWarehouse')} subtitle={t('inventory.generatedWarehouseCode')} backTo={back} backLabel={t('common.backToList')} status={warehouse && <StatusBadge text={warehouse.isActive ? t('common.active') : t('common.inactive')} tone={warehouse.isActive ? 'positive' : 'neutral'} />} actions={warehouse && !editing && has('inventory.warehouse.manage') ? <><Link className="button" to={`/inventory/warehouses/${warehouse.id}/edit?from=${encodeURIComponent(back)}`}>{t('common.edit')}</Link><button className="button" onClick={() => setConfirm(true)}>{warehouse.isActive ? t('common.deactivate') : t('common.reactivate')}</button></> : undefined} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}<Section title={editing ? t('inventory.warehouseDetails') : t('common.overview')}>{editing ? <form className="ui-form-grid ui-form-grid--3" onSubmit={e => void save(e)}>{warehouse && <FormField label={t('common.code')} hint={t('common.immutable')}><input dir="ltr" disabled value={warehouse.code} /></FormField>}<FormField label={t('inventory.warehouseType')} hint={warehouse ? t('common.immutable') : t('inventory.warehouseTypeHint')} required><select required disabled={Boolean(warehouse)} value={form.warehouseType} onChange={e => setForm({ ...form, warehouseType: e.target.value })}>{warehouseTypes.map(value => <option key={value} value={value}>{t(`inventory.warehouseTypes.${value}`)}</option>)}</select></FormField><FormField label={t('common.nameFa')} required><input required value={form.nameFa} onChange={e => setForm({ ...form, nameFa: e.target.value })} /></FormField><FormField label={t('common.nameEn')}><input dir="ltr" value={form.nameEn} onChange={e => setForm({ ...form, nameEn: e.target.value })} /></FormField><FormField label={t('inventory.addressFa')} required><textarea required value={form.addressFa} onChange={e => setForm({ ...form, addressFa: e.target.value })} /></FormField><FormField label={t('inventory.addressEn')}><textarea dir="ltr" value={form.addressEn} onChange={e => setForm({ ...form, addressEn: e.target.value })} /></FormField><FormField label={t('inventory.searchResponsible')}><input value={userSearch} onChange={e => setUserSearch(e.target.value)} /></FormField><FormField label={t('inventory.responsible')} required><select required value={form.primaryResponsibleUserId} onChange={e => setForm({ ...form, primaryResponsibleUserId: e.target.value })}><option value="">{t('common.notSet')}</option>{users.map(user => <option value={user.id} key={user.id}>{user.fullName} — {user.userName}</option>)}</select></FormField><FormField label={t('common.notes')}><textarea value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} /></FormField><div className="inline-actions"><button className="button button--primary" type="submit">{t('common.save')}</button><Link className="button" to={back}>{t('common.cancel')}</Link></div></form> : warehouse && <dl className="ui-detail-list"><div><dt>{t('inventory.warehouse')}</dt><dd>{localizedName(warehouse, i18n.resolvedLanguage)}</dd></div><div><dt>{t('inventory.warehouseType')}</dt><dd><StatusBadge text={t(`inventory.warehouseTypes.${warehouse.warehouseType}`)} tone={warehouse.includeInMrpAvailable ? 'positive' : 'warning'} /></dd></div><div><dt>{t('inventory.mrpAvailability')}</dt><dd>{warehouse.includeInMrpAvailable ? t('inventory.includedInMrp') : t('inventory.excludedFromMrp')}</dd></div><div><dt>{t('inventory.location')}</dt><dd>{displayAddress || '—'}</dd></div><div><dt>{t('inventory.responsible')}</dt><dd>{warehouse.primaryResponsibleUser?.fullName || '—'}<small>{warehouse.primaryResponsibleUser?.userName}</small></dd></div><div><dt>{t('common.notes')}</dt><dd>{warehouse.notes || '—'}</dd></div></dl>}</Section><ConfirmationDialog open={confirm} title={t('common.stateConfirmTitle')} confirmLabel={t('common.confirm')} cancelLabel={t('common.cancel')} onConfirm={() => void state()} onCancel={() => setConfirm(false)} /></main>
}

function TransactionList() {
  const { t, i18n } = useTranslation(); const query = useListQuery(25); const [rows, setRows] = useState<Transaction[]>([]); const [total, setTotal] = useState(0); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const type = query.value('type'); const from = query.value('from'); const to = query.value('to'); const display = (x: { nameFa: string; nameEn?: string | null }) => localizedName(x, i18n.resolvedLanguage)
  useEffect(() => { let active = true; const language = i18n.resolvedLanguage ?? 'fa-IR'; if (!dateFilterReady(from, language) || !dateFilterReady(to, language)) return () => { active = false }; void (async () => { try { const q = buildTransactionListQuery(type, query.page, query.pageSize); if (from) q.set('from', await canonicalDate(from, language)); if (to) q.set('to', await canonicalDate(to, language)); const x = await get<Page<Transaction>>(`/inventory/transactions?${q}`); if (active) { setRows(x.items); setTotal(x.totalCount) } } catch (e) { if (active) setError(message(e, t)) } finally { if (active) setLoading(false) } })(); return () => { active = false } }, [from, i18n.resolvedLanguage, query.page, query.pageSize, t, to, type])
  return <main className="app-shell"><PageHeader title={t('inventory.ledger')} subtitle={t('inventory.historyOnly')} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}<FilterBar label={t('common.filterBar')}><FormField label={t('inventory.type')}><select value={type} onChange={e => query.update({ type: e.target.value }, true)}><option value="">{t('common.all')}</option>{transactionTypes.map(x => <option key={x}>{x}</option>)}</select></FormField><DateFilterField label={t('common.from')} value={from} setValue={value => query.update({ from: value }, true)} /><DateFilterField label={t('common.to')} value={to} setValue={value => query.update({ to: value }, true)} /></FilterBar><section className="ui-table-surface"><TableToolbar title={t('inventory.ledger')} count={t('common.count', { count: total })} /><DataTable headers={[t('inventory.effectiveDate'), t('inventory.type'), t('inventory.item'), t('inventory.warehouse'), t('inventory.enteredQuantity'), t('inventory.baseQuantity')]} loading={loading} empty={!rows.length} filtered={Boolean(type || from || to)} loadingLabel={t('common.loading')} emptyTitle={t('common.emptyTitle')} noResultTitle={t('common.noResultsTitle')}>{rows.map(x => <tr key={x.id}><td><Link className="ui-technical" to={`/inventory/ledger/${x.id}`}>{formatBusinessDate(x.effectiveDate, i18n.resolvedLanguage ?? 'fa-IR')}</Link></td><td><StatusBadge text={t(`inventory.${x.transactionType}`)} tone={transactionTone(x.transactionType)} /></td><td>{x.item.code} — {display(x.item)}</td><td>{x.warehouse.code}{x.destinationWarehouse ? ` → ${x.destinationWarehouse.code}` : ''}</td><td className="ui-number">{formatOperationalNumber(x.enteredQuantity, i18n.resolvedLanguage)} {x.transactionUnit.code}</td><td className="ui-number">{formatOperationalNumber(x.quantity, i18n.resolvedLanguage)} {x.unit.code}</td></tr>)}</DataTable><PageNav page={query.page} pageSize={query.pageSize} total={total} change={page => query.update({ page })} /></section></main>
}

function TransactionObject() {
  const { t, i18n } = useTranslation(); const { has } = useAuth(); const { id } = useParams(); const [row, setRow] = useState<Transaction>(); const [error, setError] = useState(''); const [reason, setReason] = useState(''); const [confirm, setConfirm] = useState(false); const navigate = useNavigate(); const display = (x: { nameFa: string; nameEn?: string | null }) => localizedName(x, i18n.resolvedLanguage)
  useEffect(() => { void get<Transaction>(`/inventory/transactions/${id}`).then(setRow).catch(e => setError(message(e, t))) }, [id, t])
  async function reverse() { try { const result = await request<Transaction>(`/inventory/transactions/${id}/reverse`, 'POST', { reason }); navigate(`/inventory/ledger/${result.id}`) } catch (e) { setError(message(e, t)); setConfirm(false) } }
  const workflowOwned = row?.sourceDocumentType?.startsWith('INTERNAL_TRANSFER_')
  return <main className="app-shell"><PageHeader title={row ? `${t(`inventory.${row.transactionType}`)} — ${formatBusinessDate(row.effectiveDate, i18n.resolvedLanguage ?? 'fa-IR')}` : t('inventory.transaction')} backTo="/inventory/ledger" backLabel={t('common.backToList')} actions={row && row.transactionType !== 'REVERSAL' && !workflowOwned && has('inventory.transaction.reverse') ? <button className="button button--danger" onClick={() => setConfirm(true)}>{t('inventory.reverse')}</button> : undefined} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}{row && <Section title={t('common.overview')}><dl className="ui-detail-list"><div><dt>{t('inventory.item')}</dt><dd>{row.item.code} — {display(row.item)}</dd></div><div><dt>{t('inventory.warehouse')}</dt><dd>{row.warehouse.code} — {display(row.warehouse)}</dd></div><div><dt>{t('inventory.enteredQuantity')}</dt><dd className="ui-technical">{row.enteredQuantity} {display(row.transactionUnit)}</dd></div><div><dt>{t('inventory.baseQuantity')}</dt><dd className="ui-technical">{row.quantity} {display(row.unit)}</dd></div><div><dt>{t('inventory.conversionFactor')}</dt><dd className="ui-technical">{row.conversionFactorToBase}</dd></div><div><dt>{t('inventory.source')}</dt><dd>{row.sourceDocumentType || '—'}</dd></div><div><dt>{t('inventory.reason')}</dt><dd>{row.reason || '—'}</dd></div></dl></Section>}<ConfirmationDialog open={confirm} title={t('inventory.reverse')} description={t('inventory.historyOnly')} confirmLabel={t('common.confirm')} cancelLabel={t('common.cancel')} onConfirm={() => void reverse()} onCancel={() => setConfirm(false)}><FormField label={t('inventory.reason')} required><input autoFocus required value={reason} onChange={e => setReason(e.target.value)} /></FormField></ConfirmationDialog></main>
}

function PostingPage({ operation }: { operation: Operation }) {
  const { t, i18n } = useTranslation(); const navigate = useNavigate(); const [items, setItems] = useState<Item[]>([]); const [itemTotal, setItemTotal] = useState(0); const [itemPage, setItemPage] = useState(1); const [itemSearch, setItemSearch] = useState(''); const [warehouses, setWarehouses] = useState<Warehouse[]>([]); const [warehousePage, setWarehousePage] = useState(1); const [warehouseTotal, setWarehouseTotal] = useState(0); const [warehouseSearch, setWarehouseSearch] = useState(''); const [transactionUnits, setTransactionUnits] = useState<UnitConversion[]>([]); const [form, setForm] = useState({ itemId: '', warehouseId: '', transactionUnitId: '', quantity: '', effectiveDate: '', reason: '', direction: 'IN' }); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const display = (x: { nameFa: string; nameEn?: string | null }) => localizedName(x, i18n.resolvedLanguage)
  usePagedPickers(itemSearch, itemPage, setItems, setItemTotal, warehouseSearch, warehousePage, setWarehouses, setWarehouseTotal, setError, t)
  useEffect(() => { void defaultBusinessDate(i18n.resolvedLanguage ?? 'fa-IR').then(value => setForm(current => ({ ...current, effectiveDate: current.effectiveDate || value }))) }, [i18n.resolvedLanguage])
  useEffect(() => { if (!form.itemId) { void Promise.resolve().then(() => setTransactionUnits([])); return } void get<UnitConversionList>(`/inventory/items/${form.itemId}/units`).then(value => { setTransactionUnits(value.items); setForm(current => ({ ...current, transactionUnitId: value.items.some(row => row.transactionUnit.id === current.transactionUnitId) ? current.transactionUnitId : value.item.baseUnit.id })) }).catch(e => setError(message(e, t))) }, [form.itemId, t])
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); try { const effectiveDate = await canonicalDate(form.effectiveDate, i18n.resolvedLanguage ?? 'fa-IR'); const base = { itemId: form.itemId, warehouseId: form.warehouseId, transactionUnitId: form.transactionUnitId, quantity: Number(form.quantity), effectiveDate, reason: form.reason || null }; const endpoint = operation === 'OPENING' ? 'openings' : operation === 'RECEIPT' ? 'receipts' : operation === 'ISSUE' ? 'issues' : 'adjustments'; const body = operation === 'ADJUSTMENT' ? { ...base, direction: form.direction } : base; const result = await request<Transaction>(`/inventory/${endpoint}`, 'POST', body); navigate(`/inventory/ledger/${result.id}`) } catch (e) { setError(message(e, t)) } finally { setBusy(false) } }
  const selectedUnit = transactionUnits.find(row => row.transactionUnit.id === form.transactionUnitId)
  return <main className="app-shell"><PageHeader title={t(`inventory.operation${operation}`)} subtitle={t(`inventory.operation${operation}Hint`)} backTo="/inventory/ledger" backLabel={t('common.backToList')} />{operation === 'OPENING' && <MessageStrip tone="warning">{t('inventory.openingWarning')}</MessageStrip>}{error && <MessageStrip tone="critical">{error}</MessageStrip>}<Section title={t(`inventory.operation${operation}`)}><form className="ui-form-grid ui-form-grid--3" onSubmit={e => void submit(e)}><PickerFields items={items} itemTotal={itemTotal} itemPage={itemPage} itemSearch={itemSearch} setItemPage={setItemPage} setItemSearch={setItemSearch} itemId={form.itemId} setItemId={value => setForm({ ...form, itemId: value, transactionUnitId: '' })} warehouses={warehouses} warehouseTotal={warehouseTotal} warehousePage={warehousePage} warehouseSearch={warehouseSearch} setWarehousePage={setWarehousePage} setWarehouseSearch={setWarehouseSearch} warehouseId={form.warehouseId} setWarehouseId={value => setForm({ ...form, warehouseId: value })} display={display} />{operation === 'ADJUSTMENT' && <FormField label={t('inventory.direction')} required><select value={form.direction} onChange={e => setForm({ ...form, direction: e.target.value })}><option value="IN">{t('inventory.adjustIn')}</option><option value="OUT">{t('inventory.adjustOut')}</option></select></FormField>}<FormField label={t('inventory.transactionUnit')} required><select required value={form.transactionUnitId} onChange={e => setForm({ ...form, transactionUnitId: e.target.value })}><option value="">{t('common.notSet')}</option>{transactionUnits.map(row => <option key={row.transactionUnit.id} value={row.transactionUnit.id}>{row.transactionUnit.code} — {display(row.transactionUnit)}</option>)}</select></FormField><FormField label={t('inventory.enteredQuantity')} hint={selectedUnit && form.quantity ? t('inventory.basePreview', { quantity: Number(form.quantity) * selectedUnit.factorToBase, unit: selectedUnit.baseUnit.code }) : undefined} required><input required type="number" min="0.000001" step="0.000001" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} /></FormField><BusinessDateField value={form.effectiveDate} setValue={value => setForm({ ...form, effectiveDate: value })} /><FormField label={t('inventory.reason')} required={operation === 'ADJUSTMENT'}><textarea required={operation === 'ADJUSTMENT'} value={form.reason} onChange={e => setForm({ ...form, reason: e.target.value })} /></FormField><button className="button button--primary" disabled={busy}>{busy ? t('common.loading') : t('inventory.post')}</button></form></Section></main>
}

function TransferList() {
  const { t, i18n } = useTranslation(); const { has } = useAuth(); const location = useLocation(); const query = useListQuery(25); const search = query.value('search'); const status = query.value('status'); const [rows, setRows] = useState<Transfer[]>([]); const [total, setTotal] = useState(0); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const display = (x: { nameFa: string; nameEn?: string | null }) => localizedName(x, i18n.resolvedLanguage)
  useEffect(() => { const q = new URLSearchParams({ search, status, page: String(query.page), pageSize: String(query.pageSize) }); void get<Page<Transfer>>(`/inventory/transfers?${q}`).then(x => { setRows(x.items); setTotal(x.totalCount) }).catch(e => setError(message(e, t))).finally(() => setLoading(false)) }, [query.page, query.pageSize, search, status, t])
  return <main className="app-shell"><PageHeader title={t('inventory.transfers')} subtitle={t('inventory.transferHint')} actions={has('inventory.transfer.post') ? <Link className="button button--primary" to={`/inventory/transfers/new?from=${currentListContext(location.pathname, location.search)}`}>{t('inventory.newTransfer')}</Link> : undefined} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}<FilterBar label={t('common.filterBar')}><FormField label={t('common.search')}><input value={search} onChange={e => query.update({ search: e.target.value }, true)} /></FormField><FormField label={t('common.status')}><select value={status} onChange={e => query.update({ status: e.target.value }, true)}><option value="">{t('common.all')}</option>{transferStatuses.map(x => <option key={x}>{x}</option>)}</select></FormField></FilterBar><section className="ui-table-surface"><TableToolbar title={t('inventory.transfers')} count={t('common.count', { count: total })} /><DataTable headers={[t('common.code'), t('common.status'), t('inventory.item'), t('inventory.route'), t('inventory.requested'), t('inventory.received'), t('inventory.inTransit')]} loading={loading} empty={!rows.length} filtered={Boolean(search || status)} loadingLabel={t('common.loading')} emptyTitle={t('common.emptyTitle')} noResultTitle={t('common.noResultsTitle')}>{rows.map(row => <tr key={row.id}><td><Link className="technical-value" to={`/inventory/transfers/${row.id}?from=${currentListContext(location.pathname, location.search)}`}>{row.code}</Link></td><td><StatusBadge text={t(`inventory.transferStatus${row.status}`)} tone={transferTone(row.status)} /></td><td>{row.item.code} — {display(row.item)}</td><td>{row.sourceWarehouse.code} → {row.destinationWarehouse.code}</td><td className="technical-value">{row.requestedQuantity}</td><td className="technical-value">{row.receivedQuantity}</td><td className="technical-value">{row.inTransitQuantity}</td></tr>)}</DataTable><PageNav page={query.page} pageSize={query.pageSize} total={total} change={page => query.update({ page })} /></section></main>
}

function TransferCreate() {
  const { t, i18n } = useTranslation(); const { id } = useParams(); const navigate = useNavigate(); const back = useListReturn('/inventory/transfers'); const [transfer, setTransfer] = useState<Transfer>(); const [items, setItems] = useState<Item[]>([]); const [itemTotal, setItemTotal] = useState(0); const [itemPage, setItemPage] = useState(1); const [itemSearch, setItemSearch] = useState(''); const [warehouses, setWarehouses] = useState<Warehouse[]>([]); const [warehousePage, setWarehousePage] = useState(1); const [warehouseTotal, setWarehouseTotal] = useState(0); const [warehouseSearch, setWarehouseSearch] = useState(''); const [transactionUnits, setTransactionUnits] = useState<UnitConversion[]>([]); const [form, setForm] = useState({ itemId: '', sourceWarehouseId: '', destinationWarehouseId: '', transactionUnitId: '', quantity: '', reason: '' }); const [error, setError] = useState(''); const display = (x: { nameFa: string; nameEn?: string | null }) => localizedName(x, i18n.resolvedLanguage)
  usePagedPickers(itemSearch, itemPage, setItems, setItemTotal, warehouseSearch, warehousePage, setWarehouses, setWarehouseTotal, setError, t)
  useEffect(() => { if (!id) return; void get<Transfer>(`/inventory/transfers/${id}`).then(value => { if (value.status !== 'DRAFT') throw new Error(t('inventory.transferDraftHint')); setTransfer(value); setItems(current => uniqueById([...current, value.item])); setWarehouses(current => uniqueById([...current, value.sourceWarehouse, value.destinationWarehouse])); setForm({ itemId: value.item.id, sourceWarehouseId: value.sourceWarehouse.id, destinationWarehouseId: value.destinationWarehouse.id, transactionUnitId: value.transactionUnit.id, quantity: String(value.enteredRequestedQuantity), reason: value.reason || '' }) }).catch(e => setError(message(e, t))) }, [id, t])
  useEffect(() => { if (!form.itemId) { void Promise.resolve().then(() => setTransactionUnits([])); return } void get<UnitConversionList>(`/inventory/items/${form.itemId}/units`).then(value => { setTransactionUnits(value.items); setForm(current => ({ ...current, transactionUnitId: value.items.some(row => row.transactionUnit.id === current.transactionUnitId) ? current.transactionUnitId : value.item.baseUnit.id })) }).catch(e => setError(message(e, t))) }, [form.itemId, t])
  async function submit(event: FormEvent) { event.preventDefault(); try { const body = { ...form, quantity: Number(form.quantity), reason: form.reason || null, ...(id ? { expectedVersion: transfer!.version } : {}) }; const result = await request<Transfer>(id ? `/inventory/transfers/${id}` : '/inventory/transfers', id ? 'PUT' : 'POST', body); navigate(`/inventory/transfers/${result.id}?from=${encodeURIComponent(back)}`) } catch (e) { setError(message(e, t)) } }
  const selectedUnit = transactionUnits.find(row => row.transactionUnit.id === form.transactionUnitId)
  return <main className="app-shell"><PageHeader title={id ? `${t('common.edit')} — ${transfer?.code ?? ''}` : t('inventory.newTransfer')} subtitle={t('inventory.transferDraftHint')} backTo={id ? `/inventory/transfers/${id}?from=${encodeURIComponent(back)}` : back} backLabel={t('common.backToList')} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}<Section title={t('inventory.transferDetails')}><form className="ui-form-grid ui-form-grid--3" onSubmit={e => void submit(e)}><FormField label={t('inventory.searchItem')}><input value={itemSearch} onChange={e => { setItemSearch(e.target.value); setItemPage(1) }} /></FormField><FormField label={t('inventory.item')} required><select required value={form.itemId} onChange={e => setForm({ ...form, itemId: e.target.value, transactionUnitId: '' })}><option value="">{t('common.notSet')}</option>{items.map(x => <option value={x.id} key={x.id}>{x.code} — {display(x)}</option>)}</select><PickerPager page={itemPage} total={itemTotal} setPage={setItemPage} /></FormField><FormField label={t('inventory.searchWarehouse')}><input value={warehouseSearch} onChange={e => { setWarehouseSearch(e.target.value); setWarehousePage(1) }} /></FormField><FormField label={t('inventory.fromWarehouse')} required><select required value={form.sourceWarehouseId} onChange={e => setForm({ ...form, sourceWarehouseId: e.target.value })}><option value="">{t('common.notSet')}</option>{warehouses.map(x => <option value={x.id} key={x.id}>{x.code} — {display(x)}</option>)}</select></FormField><FormField label={t('inventory.toWarehouse')} required><select required value={form.destinationWarehouseId} onChange={e => setForm({ ...form, destinationWarehouseId: e.target.value })}><option value="">{t('common.notSet')}</option>{warehouses.map(x => <option value={x.id} key={x.id}>{x.code} — {display(x)}</option>)}</select><PickerPager page={warehousePage} total={warehouseTotal} setPage={setWarehousePage} /></FormField><FormField label={t('inventory.transactionUnit')} required><select required value={form.transactionUnitId} onChange={e => setForm({ ...form, transactionUnitId: e.target.value })}><option value="">{t('common.notSet')}</option>{transactionUnits.map(row => <option key={row.transactionUnit.id} value={row.transactionUnit.id}>{row.transactionUnit.code} — {display(row.transactionUnit)}</option>)}</select></FormField><FormField label={t('inventory.enteredQuantity')} hint={selectedUnit && form.quantity ? t('inventory.basePreview', { quantity: Number(form.quantity) * selectedUnit.factorToBase, unit: selectedUnit.baseUnit.code }) : undefined} required><input required type="number" min="0.000001" step="0.000001" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} /></FormField><FormField label={t('inventory.reason')}><textarea value={form.reason} onChange={e => setForm({ ...form, reason: e.target.value })} /></FormField><button className="button button--primary">{t('common.save')}</button></form></Section></main>
}

function TransferObject() {
  const { t, i18n } = useTranslation(); const { has } = useAuth(); const { id } = useParams(); const back = useListReturn('/inventory/transfers'); const [row, setRow] = useState<Transfer>(); const [error, setError] = useState(''); const [dialog, setDialog] = useState<'dispatch' | 'receive' | 'cancel' | 'reverse' | null>(null); const [receiptId, setReceiptId] = useState(''); const [form, setForm] = useState({ quantity: '', effectiveDate: '', reason: '' }); const display = (x: { nameFa: string; nameEn?: string | null }) => localizedName(x, i18n.resolvedLanguage)
  const load = useCallback(() => get<Transfer>(`/inventory/transfers/${id}`).then(setRow).catch(e => setError(message(e, t))), [id, t]); useEffect(() => { void load() }, [load])
  async function open(next: typeof dialog, selectedReceipt = '') { setDialog(next); setReceiptId(selectedReceipt); setForm({ quantity: '', effectiveDate: await defaultBusinessDate(i18n.resolvedLanguage ?? 'fa-IR'), reason: '' }) }
  async function act() { if (!row || !dialog) return; try { if (dialog === 'dispatch') await request(`/inventory/transfers/${row.id}/dispatch`, 'POST', { effectiveDate: await canonicalDate(form.effectiveDate, i18n.resolvedLanguage ?? 'fa-IR'), expectedVersion: row.version, reason: form.reason || null }); if (dialog === 'receive') await request(`/inventory/transfers/${row.id}/receive`, 'POST', { quantity: Number(form.quantity), effectiveDate: await canonicalDate(form.effectiveDate, i18n.resolvedLanguage ?? 'fa-IR'), expectedVersion: row.version, reason: form.reason || null }); if (dialog === 'cancel') await request(`/inventory/transfers/${row.id}/cancel`, 'POST', { expectedVersion: row.version, reason: form.reason }); if (dialog === 'reverse') await request(`/inventory/transfers/${row.id}/receipts/${receiptId}/reverse`, 'POST', { expectedVersion: row.version, reason: form.reason }); setDialog(null); await load() } catch (e) { setError(message(e, t)); setDialog(null) } }
  const canOperate = has('inventory.transfer.post')
  return <main className="app-shell"><PageHeader title={row ? `${row.code} — ${t('inventory.transfer')}` : t('inventory.transfer')} subtitle={t('inventory.twoStepTransfer')} backTo={back} backLabel={t('common.backToList')} status={row && <StatusBadge text={t(`inventory.transferStatus${row.status}`)} tone={transferTone(row.status)} />} actions={row && canOperate ? <>{row.status === 'DRAFT' && <Link className="button" to={`/inventory/transfers/${row.id}/edit?from=${encodeURIComponent(back)}`}>{t('common.edit')}</Link>}{row.status === 'DRAFT' && <button className="button button--primary" onClick={() => void open('dispatch')}>{t('inventory.dispatch')}</button>}{['DISPATCHED', 'PARTIALLY_RECEIVED'].includes(row.status) && <button className="button button--primary" onClick={() => void open('receive')}>{t('inventory.receiveTransfer')}</button>}{['DRAFT', 'DISPATCHED'].includes(row.status) && <button className="button" onClick={() => void open('cancel')}>{t('common.cancel')}</button>}</> : undefined} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}{row && <><section className="inventory-transfer-flow" aria-label={t('inventory.transferProgress')}>{transferStatuses.slice(0, 4).map(status => <div className={transferReached(row.status, status) ? 'done' : ''} key={status}><span /><strong>{t(`inventory.transferStatus${status}`)}</strong></div>)}</section><section className="inventory-kpi-grid inventory-kpi-grid--three"><Kpi icon={<PackageMinus />} label={t('inventory.dispatched')} value={row.dispatchedQuantity} /><Kpi icon={<PackagePlus />} label={t('inventory.received')} value={row.receivedQuantity} /><Kpi icon={<ArrowLeftRight />} label={t('inventory.inTransit')} value={row.inTransitQuantity} /></section><Section title={t('inventory.transferDetails')}><dl className="ui-detail-list"><div><dt>{t('inventory.item')}</dt><dd>{row.item.code} — {display(row.item)}</dd></div><div><dt>{t('inventory.route')}</dt><dd>{row.sourceWarehouse.code} — {display(row.sourceWarehouse)} → {row.destinationWarehouse.code} — {display(row.destinationWarehouse)}</dd></div><div><dt>{t('inventory.requested')}</dt><dd className="technical-value">{row.enteredRequestedQuantity} {display(row.transactionUnit)}</dd></div><div><dt>{t('inventory.baseQuantity')}</dt><dd className="technical-value">{row.requestedQuantity} {display(row.unit)}</dd></div><div><dt>{t('inventory.conversionFactor')}</dt><dd className="technical-value">{row.conversionFactorToBase}</dd></div><div><dt>{t('inventory.dispatchDate')}</dt><dd>{formatBusinessDate(row.dispatchDate, i18n.resolvedLanguage ?? 'fa-IR')}</dd></div><div><dt>{t('inventory.reason')}</dt><dd>{row.reason || '—'}</dd></div></dl></Section><Section title={t('inventory.transferReceipts')}><DataTable headers={[t('inventory.effectiveDate'), t('inventory.enteredQuantity'), t('inventory.baseQuantity'), t('inventory.reason'), t('common.status'), t('common.actions')]} empty={!row.receipts.length} loadingLabel={t('common.loading')} emptyTitle={t('inventory.noTransferReceipts')} noResultTitle={t('common.noResultsTitle')}>{row.receipts.map(receipt => <tr key={receipt.id}><td>{formatBusinessDate(receipt.effectiveDate, i18n.resolvedLanguage ?? 'fa-IR')}</td><td className="technical-value">{receipt.enteredQuantity} {receipt.transactionUnit.code}</td><td className="technical-value">{receipt.quantity} {row.unit.code}</td><td>{receipt.reason || '—'}</td><td><StatusBadge text={receipt.isReversed ? t('inventory.reversed') : t('inventory.effective')} tone={receipt.isReversed ? 'neutral' : 'positive'} /></td><td>{!receipt.isReversed && has('inventory.transaction.reverse') && <button className="button button--compact" onClick={() => void open('reverse', receipt.id)}>{t('inventory.reverse')}</button>}</td></tr>)}</DataTable></Section></>}
    <ConfirmationDialog open={Boolean(dialog)} title={dialog ? t(`inventory.${dialog}Dialog`) : ''} confirmLabel={t('common.confirm')} cancelLabel={t('common.cancel')} onConfirm={() => void act()} onCancel={() => setDialog(null)}>{dialog === 'receive' && <FormField label={`${t('inventory.enteredQuantity')} (${row?.transactionUnit.code ?? ''})`} required><input autoFocus type="number" min="0.000001" step="0.000001" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} /></FormField>}{(dialog === 'dispatch' || dialog === 'receive') && <BusinessDateField value={form.effectiveDate} setValue={value => setForm({ ...form, effectiveDate: value })} />}<FormField label={t('inventory.reason')} required={dialog === 'cancel' || dialog === 'reverse'}><textarea autoFocus={dialog === 'cancel' || dialog === 'reverse'} required={dialog === 'cancel' || dialog === 'reverse'} value={form.reason} onChange={e => setForm({ ...form, reason: e.target.value })} /></FormField></ConfirmationDialog></main>
}

function PickerFields({ items, itemTotal, itemPage, itemSearch, setItemPage, setItemSearch, itemId, setItemId, warehouses, warehouseTotal, warehousePage, warehouseSearch, setWarehousePage, setWarehouseSearch, warehouseId, setWarehouseId, display }: { items: Item[]; itemTotal: number; itemPage: number; itemSearch: string; setItemPage: (v: number) => void; setItemSearch: (v: string) => void; itemId: string; setItemId: (v: string) => void; warehouses: Warehouse[]; warehouseTotal: number; warehousePage: number; warehouseSearch: string; setWarehousePage: (v: number) => void; setWarehouseSearch: (v: string) => void; warehouseId: string; setWarehouseId: (v: string) => void; display: (x: { nameFa: string; nameEn?: string | null }) => string }) {
  const { t } = useTranslation(); return <><FormField label={t('inventory.searchItem')}><input value={itemSearch} onChange={e => { setItemSearch(e.target.value); setItemPage(1) }} /></FormField><FormField label={t('inventory.item')} required><select required value={itemId} onChange={e => setItemId(e.target.value)}><option value="">{t('common.notSet')}</option>{items.map(x => <option value={x.id} key={x.id}>{x.code} — {display(x)}</option>)}</select><PickerPager page={itemPage} total={itemTotal} setPage={setItemPage} /></FormField><FormField label={t('inventory.searchWarehouse')}><input value={warehouseSearch} onChange={e => { setWarehouseSearch(e.target.value); setWarehousePage(1) }} /></FormField><FormField label={t('inventory.warehouse')} required><select required value={warehouseId} onChange={e => setWarehouseId(e.target.value)}><option value="">{t('common.notSet')}</option>{warehouses.map(x => <option value={x.id} key={x.id}>{x.code} — {display(x)}</option>)}</select><PickerPager page={warehousePage} total={warehouseTotal} setPage={setWarehousePage} /></FormField></>
}

function PickerPager({ page, total, setPage }: { page: number; total: number; setPage: (value: number) => void }) { const { t } = useTranslation(); const pages = Math.max(1, Math.ceil(total / 25)); return <span className="picker-pagination"><button type="button" disabled={page <= 1} onClick={() => setPage(page - 1)}>{t('common.previous')}</button><span>{page}/{pages}</span><button type="button" disabled={page >= pages} onClick={() => setPage(page + 1)}>{t('common.next')}</button></span> }
function PageNav({ page, pageSize, total, change }: { page: number; pageSize: number; total: number; change: (page: number) => void }) { const { t } = useTranslation(); return <Pagination page={page} pageSize={pageSize} totalCount={total} onPageChange={change} previousLabel={t('common.previous')} nextLabel={t('common.next')} summary={t('common.page', { page, pages: Math.max(1, Math.ceil(total / pageSize)), count: total })} /> }
function BusinessDateField({ value, setValue }: { value: string; setValue: (value: string) => void }) { const { t, i18n } = useTranslation(); const persian = !i18n.resolvedLanguage?.startsWith('en'); return <FormField label={t('inventory.effectiveDate')} hint={persian ? t('inventory.jalaliDateHint') : undefined} required><input required type={persian ? 'text' : 'date'} inputMode={persian ? 'numeric' : undefined} dir="ltr" placeholder={persian ? '14050609' : undefined} value={value} onChange={e => setValue(persian ? toAsciiDigits(e.target.value).replace(/[^0-9]/g, '').slice(0, 8) : e.target.value)} /></FormField> }
function DateFilterField({ label, value, setValue }: { label: string; value: string; setValue: (value: string) => void }) { const { t, i18n } = useTranslation(); const persian = !i18n.resolvedLanguage?.startsWith('en'); return <FormField label={label} hint={persian ? t('inventory.jalaliDateHint') : undefined}><input type={persian ? 'text' : 'date'} inputMode={persian ? 'numeric' : undefined} dir="ltr" placeholder={persian ? '14050609' : undefined} value={value} onChange={e => setValue(persian ? toAsciiDigits(e.target.value).replace(/[^0-9]/g, '').slice(0, 8) : e.target.value)} /></FormField> }

function usePagedPickers(itemSearch: string, itemPage: number, setItems: (rows: Item[]) => void, setItemTotal: (total: number) => void, warehouseSearch: string, warehousePage: number, setWarehouses: (rows: Warehouse[]) => void, setWarehouseTotal: (total: number) => void, setError: (error: string) => void, t: (key: string) => string) {
  useEffect(() => { const timer = window.setTimeout(() => { const q = new URLSearchParams({ search: itemSearch, page: String(itemPage), pageSize: '25' }); void get<Page<Item>>(`/inventory/items?${q}`).then(x => { setItems(x.items); setItemTotal(x.totalCount) }).catch(e => setError(message(e, t))) }, 150); return () => window.clearTimeout(timer) }, [itemPage, itemSearch, setError, setItemTotal, setItems, t])
  useEffect(() => { const timer = window.setTimeout(() => { const q = new URLSearchParams({ search: warehouseSearch, page: String(warehousePage), pageSize: '25' }); void get<Page<Warehouse>>(`/inventory/warehouses?${q}`).then(x => { setWarehouses(x.items); setWarehouseTotal(x.totalCount) }).catch(e => setError(message(e, t))) }, 150); return () => window.clearTimeout(timer) }, [setError, setWarehouseTotal, setWarehouses, t, warehousePage, warehouseSearch])
}

async function defaultBusinessDate(language: string) { const body = await get<{ tehranBusinessDate: string; jalaliDate: string }>('/planning/business-date'); return language.startsWith('en') ? body.tehranBusinessDate : body.jalaliDate }
async function canonicalDate(value: string, language: string) { if (language.startsWith('en')) return value; const normalized = normalizeJalaliDateInput(value); if (!normalized) throw new Error('تاریخ شمسی باید ۸ رقم و به‌صورت YYYYMMDD باشد.'); const response = await request<{ gregorianDate: string }>('/planning/resolve-jalali-date', 'POST', { jalaliDate: normalized }); return response.gregorianDate }
function dateFilterReady(value: string, language: string) { return !value || language.startsWith('en') || toAsciiDigits(value).replace(/[^0-9]/g, '').length === 8 }
function uniqueById<T extends { id: string }>(rows: T[]) { return [...new Map(rows.map(row => [row.id, row])).values()] }
function transferTone(status: string): 'positive' | 'warning' | 'critical' | 'information' | 'neutral' { return status === 'RECEIVED' ? 'positive' : status === 'CANCELLED' ? 'neutral' : status === 'PARTIALLY_RECEIVED' ? 'warning' : status === 'DISPATCHED' ? 'information' : 'neutral' }
function transactionTone(type: string): 'positive' | 'warning' | 'critical' | 'information' | 'neutral' { return ['RECEIPT', 'OPENING', 'ADJ_IN'].includes(type) ? 'positive' : ['ISSUE', 'ADJ_OUT'].includes(type) ? 'warning' : type === 'REVERSAL' ? 'neutral' : 'information' }
function transferReached(current: string, target: string) { const order = ['DRAFT', 'DISPATCHED', 'PARTIALLY_RECEIVED', 'RECEIVED']; return current !== 'CANCELLED' && order.indexOf(current) >= order.indexOf(target) }
const transactionTypes = ['OPENING', 'RECEIPT', 'ISSUE', 'ADJ_IN', 'ADJ_OUT', 'TRANSFER', 'REVERSAL']
const transferStatuses = ['DRAFT', 'DISPATCHED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'CANCELLED']
const warehouseTypes = ['STORAGE', 'PRODUCTION_STAGING', 'FINISHED_GOODS']
async function get<T>(path: string): Promise<T> { const response = await fetch(`${api}${path}`); if (!response.ok) throw new Error(await problem(response)); return response.json() }
async function request<T = unknown>(path: string, method: string, body: object): Promise<T> { const response = await fetch(`${api}${path}`, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); if (!response.ok) throw new Error(await problem(response)); return response.json() }
async function problem(response: Response) { const body = await response.json().catch(() => null) as { detail?: string; code?: string; errors?: Record<string, string[]> } | null; return [body?.code, body?.detail, ...Object.values(body?.errors ?? {}).flat()].filter(Boolean).join(' — ') || `HTTP ${response.status}` }
function message(error: unknown, t: (key: string) => string) { return error instanceof Error ? error.message : t('common.error') }
